&lt;span class="nt"&gt;&amp;lt;Link&amp;gt;&lt;/span&gt;            →  &lt;span class="nt"&gt;&amp;lt;Link&amp;gt;&lt;/span&gt;
useNavigate()     →  useRouter()
notFound()        →  notFound()
pendingComponent  →  loading.tsx
